/**
 * Dropdown filter
 *
 * @module patterns/dropdown-filter/dropdown-filter
 * @author Web Development
 * @copyright City St George's, University of London 2019
 */

const className = 'dropdown-filter';

let showAll = '',
    version = '',
    id = '';

/**
 * Entry function: loops through and hides list items, sets up event listener on
 * child select box
 *
 * This pattern covers the original dropdown filter pattern, as well as the v26 version used on the new course pages.
 * The original version's HTML structure differs where the entire pattern, the select box, and the list items are all contained within a single div.
 * The v26 version has the select box in a separate div from the list items, which are contained in a ul with a data-group class.
 * The v26 version also has a data-version attribute on the ul to differentiate it from other ul elements on the page.
 *
 * @param {HTMLElement} element: the dropdown div containing all elements
 */
function prepareDropdown(element) {
    version = element.dataset.version;
    id = element.dataset.id;

    if (version && !id) {
        console.log(
            `Dropdown filter pattern with version ${version} is missing a data-id attribute.`
        );
    }

    let dataGroups, listItems;

    // Only get direct children. Note: the tabs pattern clones its panel
    // content (accordionize in prepareAccordionTabs.js) to build the mobile
    // accordion version *before* this runs, so the same data-id can exist
    // on more than one <ul> at this point. Treat the first as canonical for
    // building the select's options (so countries aren't listed twice), but
    // keep every copy in sync so both the desktop and mobile markup work.
    if (version === 'v26') {
        dataGroups = Array.from(
            document.querySelectorAll(
                `ul.data-group[data-version="v26"][data-id="${id}"]`
            )
        );
        listItems = dataGroups[0].querySelectorAll(':scope > li');
    } else {
        dataGroups = [element.querySelector('ul.data-group')];
        listItems = element.querySelectorAll('ul.data-group > li');
    }

    const firstItemVisible = element.dataset.firstItemShow;

    // Check if all items should be displayed on load
    showAll = element.dataset.displayAll;

    // Hide list items in every copy of the group
    dataGroups.forEach((group) =>
        hideListItems(
            group.querySelectorAll(':scope > li'),
            firstItemVisible,
            showAll
        )
    );

    // Insert the select box to toggle items
    insertSelect(listItems, dataGroups[0], element, firstItemVisible);

    // Display list items on select change
    const select = element.querySelector('.dropdown-filter__select');
    select.addEventListener('change', (e) => selectChange(e));
}

/**
 * Hide list items: both functions require all list items to be hidden.
 * Ths function takes care of this
 *
 * @param {HTMLElements} items - The list of items to hide.
 * @param {boolean} firstItemVisible - Whether first item should be visible on load.
 * @param {boolean} showAll - Option to display all items.
 */
function hideListItems(items, firstItemVisible, showAll) {
    // Check if dropdown should show first item
    if (firstItemVisible === 'true' && showAll === 'false') {
        let itemsArray = Array.from(items);
        itemsArray[0].setAttribute('data-hidden', 'false');
        for (var i = 1; i < itemsArray.length; i++) {
            itemsArray[i].setAttribute('data-hidden', 'true');
        }
    } else if (firstItemVisible === 'false' && showAll === 'false') {
        items.forEach(function (item) {
            item.setAttribute('data-hidden', 'true');
        });
    } else if (showAll === 'true') {
        items.forEach(function (item) {
            item.setAttribute('data-hidden', 'false');
        });
    }
    // First item automatically visible is only relevant to component load. Other behaviour is applied when interacting with component.
    firstItemVisible = 'false';
}

/**
 * Insert select: build and add the select box to source
 *
 * @param {HTMLElements} items - The list of content for the select options.
 * @param {HTMLElement} dataGroupElement - The canonical data-group list to reorder/build options from.
 * @param {HTMLElement} parentElement - The element where we need to insert the select.
 * @param {boolean} firstItemVisible - Whether first item should be visible on load.
 */
function insertSelect(
    items,
    dataGroupElement,
    parentElement,
    firstItemVisible
) {
    const selectBox = document.createElement('select'),
        selectWrapper = parentElement.querySelector(
            '.wrapper--dropdown-filter__select'
        ),
        labelFor = parentElement.dataset.labelFor,
        labelValue = parentElement.dataset.labelValue,
        labelEl = document.createElement('label');

    labelEl.textContent = labelValue;
    labelEl.setAttribute('for', labelFor);
    parentElement.dataset.labelShow === 'false'
        ? (labelEl.className = 'sr-only')
        : null;

    selectBox.className = 'dropdown-filter__select';

    if (version === 'v26') {
        selectBox.classList.add('dropdown', 'dropdown--pill');
    }

    selectBox.setAttribute('id', labelFor);
    selectBox.setAttribute('name', labelFor);

    selectWrapper.append(labelEl, selectBox);

    // Add default select text if filter doesn't have show all enabled
    if (
        parentElement.dataset.displayAll === 'false' &&
        parentElement.dataset.hidePlaceholder !== 'true'
    ) {
        let noSelection = document.createElement('option');
        noSelection.text = parentElement.getAttribute('data-text');
        noSelection.setAttribute('value', 'no-selection');
        selectBox.appendChild(noSelection);
    }

    let defaultItemOverride, lastItemOverride;

    // Sort by dataset.value to display list alphabetically
    if (parentElement.dataset.alphabetical === 'true') {
        items = Array.from(items).sort((a, b) =>
            a.dataset.value < b.dataset.value
                ? -1
                : a.dataset.value > b.dataset.value
                ? 1
                : 0
        );
    } else {
        items = [...items];
    }

    // Update output list items to correct order
    for (const item of items) {
        dataGroupElement.append(item);
    }

    // Find items with first/last position overrides
    for (const item of items) {
        item.dataset.first === 'true' ? (defaultItemOverride = item) : null;
        item.dataset.last === 'true' ? (lastItemOverride = item) : null;
    }

    const itemsLength = items.length;

    // Display show all option at top of dropdown if pattern has this configuration option set as true
    if (parentElement.dataset.displayAll === 'true') {
        let showAllOption = document.createElement('li');
        showAllOption.dataset.name = `All ${parentElement.dataset.units}`;
        showAllOption.dataset.value = 'show-all';
        items.splice(0, 0, showAllOption);
    }

    // Optionally move the preferred item to the top.
    if (parentElement.dataset.firstItemTop === 'true' && defaultItemOverride) {
        const originalPosition = items.indexOf(defaultItemOverride);
        items.splice(originalPosition, 1);

        const firstPosition =
            parentElement.dataset.displayAll === 'true' ? 1 : 0;

        items.splice(firstPosition, 0, defaultItemOverride);
    }

    // Remove item with dataset.first='true' from original position in array
    let defaultItemOverridePosition = items.indexOf(defaultItemOverride);

    // Remove item with dataset.last='true' from original position in array
    if (lastItemOverride) {
        let lastPositionOriginal = items.indexOf(lastItemOverride);
        items.splice(lastPositionOriginal, 1);
        // If custom last option exists, place as last selectable option
        items.splice(itemsLength, 0, lastItemOverride);
    }

    // Iterate over each item and create/append select option
    Array.from(items).forEach((item) => {
        const dataValue = item.dataset.value,
            dataName = item.dataset.name,
            option = document.createElement('option');

        option.value = dataValue;
        option.text = dataName;

        selectBox.appendChild(option);
    });

    // Set the preferred item as selected.
    if (firstItemVisible === 'true' && showAll === 'false') {
        const options = parentElement.querySelectorAll('option');

        if (defaultItemOverride) {
            if (parentElement.dataset.firstItemTop === 'true') {
                // New behaviour: select by value after reordering.
                const selectedValue = defaultItemOverride.dataset.value;

                Array.from(selectBox.options).forEach((option) => {
                    const isSelected = option.value === selectedValue;

                    option.selected = isSelected;
                    option.defaultSelected = isSelected;
                });
            } else {
                if (lastItemOverride) {
                    // Last item override exists
                    if (parentElement.dataset.alphabetical === 'true') {
                        options[defaultItemOverridePosition].setAttribute(
                            'selected',
                            'selected'
                        );
                    } else {
                        options[defaultItemOverridePosition + 1].setAttribute(
                            'selected',
                            'selected'
                        );
                    }
                } else {
                    // Default show & no last item override
                    options[defaultItemOverridePosition + 1].setAttribute(
                        'selected',
                        'selected'
                    );
                }
            }
        }
    }
}

/**
 * Select change: respond to select change event
 *
 * @param {event} e: The select change event.
 */
function selectChange(e) {
    // Derive this instance's version/id from the select's own form, rather
    // than the shared module-level values, in case another `.dropdown-filter`
    // on the page has since overwritten them during setup.
    const dropdownFilter = e.target.closest('.dropdown-filter');
    const localVersion = dropdownFilter.dataset.version;
    const localId = dropdownFilter.dataset.id;

    // Get every copy of the group (the tabs pattern clones panel content
    // into a mobile accordion copy, so the same data-id can exist on more
    // than one <ul>). Apply the show/hide to all of them so desktop and
    // mobile stay in sync regardless of which is currently visible.
    let dataGroups;
    if (localVersion === 'v26') {
        dataGroups = Array.from(
            document.querySelectorAll(
                `ul.data-group[data-version="v26"][data-id="${localId}"]`
            )
        );
    } else {
        dataGroups = [dropdownFilter.querySelector('.data-group')];
    }

    dataGroups.forEach((dataGroup) => {
        // Get the list item corresponding to the select value chosen
        const targetListItem = dataGroup.querySelector(
            'li.data-group__item[data-value="' + e.target.value + '"]'
        );

        // Get not selected list items
        const otherListItems = dataGroup.querySelectorAll(
            'li.data-group__item:not([data-value="' + e.target.value + '"])'
        );

        // Show/hide content based on pattern's configuration options
        if (
            e.target.value !== 'show-all' &&
            e.target.value !== 'no-selection'
        ) {
            targetListItem.removeAttribute('data-hidden');
            for (const o of otherListItems) {
                o.setAttribute('data-hidden', 'true');
            }
        } else if (e.target.value === 'no-selection') {
            for (const o of otherListItems) {
                o.setAttribute('data-hidden', 'true');
            }
        }
    });
}

export default {
    launchFn: prepareDropdown,
    launchQuery: `.${className}`,
};
